import { CUSTOM_PRESET, MOMENTS, PRESETS, PRESET_CONFIG_KEYS, PRESET_IDS, SECOND_ADMIN_NOTE, SELF_APPROVAL_CLAUSES, SOLO_APPROVER_NOTE, type Preset } from './presets.js';

/**
 * `docs/presets.md`, rendered from the preset data (DevAudit-Installer#1116 WP5). The file in the
 * repository is generated by `cli/tools/generate-presets-doc.mjs` and a test fails when it differs from
 * this output, so the document, the CLI and the portal's onboarding page can never disagree.
 */

const code = (text: string): string => `\`${text}\``;
const formatValue = (value: string | number | boolean): string => (typeof value === 'string' ? code(value) : code(String(value)));

function requirementsOf(preset: Preset): string[] {
  const out: string[] = [];
  if (preset.requires.soloApprover) out.push('a portal that allows a solo approver (the project approval policy `self_allowed_with_gap`)');
  if (preset.requires.smokeTests) out.push('smoke tests (critical tests are optional)');
  if (preset.requires.fullPack) out.push('a full test pack');
  if (out.length === 0) out.push('nothing beyond a portal project');
  for (const note of preset.notes) out.push(`the project is shown with "${note}" (a different person approves, and approving needs the admin role)`);
  return out;
}

function presetSection(preset: Preset): string {
  const written = Object.entries(preset.config);
  const notWritten = PRESET_CONFIG_KEYS.filter((key) => !(key in preset.config));
  const lines: string[] = [];
  lines.push(`## Preset ${preset.id}: ${preset.name}`, '', preset.summary, '');
  lines.push('### What it writes', '', '| Key | Value |', '| --- | --- |');
  for (const [key, value] of written) lines.push(`| ${code(key)} | ${formatValue(value)} |`);
  lines.push(`| Portal approval policy (tier B, interactive only) | ${code(preset.portalPolicy)} |`, '');
  if (notWritten.length > 0) {
    lines.push(`It does not write ${notWritten.map(code).join(', ')}; switching to it removes them.`, '');
  }
  lines.push('### What runs when', '', '| Moment | What happens |', '| --- | --- |');
  MOMENTS.forEach((moment, index) => lines.push(`| ${moment.n}. ${moment.name} | ${preset.moments[index]} |`));
  lines.push('', '### Evidence and gap', '');
  lines.push(`- **Evidence produced:** ${preset.evidence}`);
  lines.push(`- **Gap carried:** ${preset.gap}`);
  lines.push(
    preset.controls.length > 0
      ? `- **Clauses with a recorded gap:** ${preset.controls.map(code).join(', ')}. ${preset.gapText}`
      : `- **Clauses with a recorded gap:** none. ${preset.gapText}`,
  );
  lines.push('', '### What it needs', '');
  for (const need of requirementsOf(preset)) lines.push(`- ${need}`);
  lines.push('');
  return lines.join('\n');
}

export function renderPresetsMarkdown(): string {
  const lines: string[] = [];
  lines.push(
    '# Onboarding presets',
    '',
    '> Generated from `core/src/presets.ts` by `cli/tools/generate-presets-doc.mjs` (run `npm run docs:presets` in `cli/`). Do not edit this file by hand: change the data and regenerate. A test fails when the two differ.',
    '',
    'A preset is a ready-made answer to the onboarding questions. `devaudit install` and `devaudit configure` offer the presets that fit your repository, show the whole resulting configuration in plain words, and let you change any one item. There are four presets and `custom`.',
    '',
    '| Preset | For | Before a merge to the release branch | After deploy | Nightly | Who approves |',
    '| --- | --- | --- | --- | --- | --- |',
  );
  for (const id of PRESET_IDS) {
    const p = PRESETS[id];
    const gate = p.config['release_gate_tier'];
    lines.push(
      `| **${p.id}** ${p.name} | ${p.summary} | ${gate ? `the ${gate} tests block` : 'no regression gate; approval only'} | ${
        p.config['post_deploy_full_regression'] === true ? 'the full pack once' : p.config['e2e_regression_enabled'] === true ? 'nothing more' : 'the release completes by itself'
      } | ${p.config['scheduled_full_regression'] ? '02:00 UTC' : 'off'} | ${p.config['approval.mode'] === 'dual_actor' ? 'a different person' : 'the author, gap recorded'} |`,
    );
  }
  lines.push('', `**custom** (always offered): ${CUSTOM_PRESET.summary}`, '');

  lines.push('## The five moments', '', '| Moment | Workflows |', '| --- | --- |');
  for (const m of MOMENTS) lines.push(`| ${m.n}. ${m.name} | ${m.workflows} |`);
  lines.push(
    '',
    'True for every preset: smoke runs at moments 1 and 2 and blocks (Quality Gates is the required check); feature tests run at moment 1 only, when the branch names a requirement and a test is tagged for it, and do not block; the approval gate at moment 3 is always on; production evidence is collected at moment 4; the quarterly review runs at moment 5. With `e2e_regression_enabled: false` there is no `e2e-regression.yml`, so the critical and full groups never run automatically.',
    '',
    '## Which preset is suggested',
    '',
    'Scan, install and doctor use one rule. Only a preset that fits your repository can be suggested; when the rule names one that cannot be offered, the next one down (C, B, A) that can is suggested, and when none can, `custom`. Preset D is never suggested: it is chosen on purpose.',
    '',
    '1. No smoke tests found: **A**.',
    '2. You need evidence for SOC 2 or ISO 27001 and a full test pack exists: **C**.',
    '3. You need evidence for SOC 2 or ISO 27001 but no full test pack exists: **B**.',
    '4. Critical or full tests exist: **B**.',
    '5. Otherwise: **A**.',
    '',
    `When the portal's approval policy is unknown (a scan makes no portal call) A and B may be suggested with the note "${SOLO_APPROVER_NOTE}". C and D are shown with "${SECOND_ADMIN_NOTE}". When C is suggested, the reason adds that D is the same without the full regression after deploy.`,
    '',
  );
  for (const id of PRESET_IDS) lines.push(presetSection(PRESETS[id]));

  lines.push(
    '## What a recorded gap means',
    '',
    `Once the portal's approval policy exists, ${SELF_APPROVAL_CLAUSES.map(code).join(' and ')} are satisfied only by an approval made by someone other than the release's creator or submitter. Under presets A and B (policy ${code('self_allowed_with_gap')}) they show as not covered after a self-approved release; under presets C and D (policy ${code('independent')}) they show as covered. Reports measure evidence readiness; they never say a project is compliant.`,
    '',
    '## Changing later',
    '',
    '- `devaudit configure` with no arguments asks the questions again with your current answers as defaults, and shows a before and after summary.',
    '- `devaudit configure set <key> <value>` changes one setting.',
    '- `devaudit doctor` reports when the configuration no longer matches the preset you chose, and `devaudit doctor --guided` walks you through each gap.',
    '- A project onboarded before presets existed has no `onboarding_preset`, which means `custom`: it is never moved onto a preset unless you choose one.',
    '',
  );
  return lines.join('\n');
}
